/* bf-12：练手局（practice）与调试强开（force）。
   · practice：本局不结算好感 / 不计每日一次 / 不写 S.breakfastDay（结算面板会标注）
   · force   ：bfCanSend 不 ok 时也放行 —— **只在 debug / 练手路径生效**：
     opts.debug 由 CS2_DEBUG.bfStart / __cs2.bfStart 注入，opts.practice 由练手卡注入；
     正常剧情（startCook→openBreakfast）与侧栏入口都不带这两个标记 → 行为一字不变。 */
const practice = !!opts.practice;
const forceOK = !!opts.force && (practice || !!opts.debug);
const chk = bfCanSend(id);
if(!chk.ok && !forceOK){ AudioSys.bad(); toast("🍳 " + chk.why); return false; }

