  S.breakfastDay = Breakfast.rules.markSent(S.breakfastDay, id, S.day);
}
const after = id ? (S.bonds[id]||0) : 0;
if(practice) AudioSys.click();
else if(res.win){ S.bfWin = true; AudioSys.good(); } else AudioSys.bad();
