/* ⚑ 跳到早餐店：数值沿用 debugState()，此时只有羁绊 20~79 的角色收得下早餐
   （hong 24 / man 24 可选；其余需先「全部解锁」或自行提升羁绊），面板空时 openBreakfast 会 toast 说明原因 */
$("dbgBf").addEventListener("click",()=>{ enterGame();
  setTimeout(()=>{ if(openBreakfast()===false) toast("早餐店需要先把羁绊提到 <b>20~79</b>"); }, 300); });

jobs.text:
/* ⚑ 跳到早餐店（bf-12 改）：以前只弹 toast —— 新档全员好感 0 → 9 张卡全灰 → 用户根本没法试玩。
   现在与「跳到麻将」体验一致：点下去**直接开一局练手局**（默认对象 fang，不结算好感）；
   想挑人就在面板里选（面板底部另有一排不受门槛限制的练手入口）。 */
$("dbgBf").addEventListener("click",()=>{ enterGame();
  setTimeout(()=>{ if(startBreakfastGame("fang", { practice:true, force:true })!==true)
    if(openBreakfast()===false) toast("早餐店模块未加载（缺 breakfast.js）"); }, 300); });
